module benchmark/solution

import std/fs (readFile, writeFile)
import std/string (split, trim, stringToInt, contains)
import std/list (length)
import std/json (Json, encode, ja, jo, kv, js, jint)
import std/option (Some, None)

pure func parseRows(rows: [string]) -> [Json] =
  match rows {
    [] => [],
    row :: rest => {
      let remaining = parseRows(rest);
      match split(trim(row), ",") {
        [name, ageText, email] => match stringToInt(trim(ageText)) {
          Some(age) =>
            if age > 0 && contains(trim(email), "@")
            then jo([kv("name", js(trim(name))), kv("age", jint(age)), kv("email", js(trim(email)))]) :: remaining
            else remaining,
          None => remaining
        },
        _ => remaining
      }
    }
  }

pure func parseCSV(content: string) -> [Json] =
  match split(content, "\n") {
    header :: rows =>
      if split(trim(header), ",") == ["name", "age", "email"]
      then parseRows(rows)
      else [],
    [] => []
  }

export func main() -> () ! {IO, FS} {
  writeFile("users.csv", "name,age,email\nAlice,30,alice@example.com\nBob,25,bob@example.com\nCarol,35,carol@example.com\n");
  let users = parseCSV(readFile("users.csv"));
  writeFile("users.json", encode(ja(users)));
  println("Converted ${length(users)} valid rows to users.json")
}

